"""Writes results/figures/FIGURE_CAPTIONS.md. Every number is read from results/*.csv, results.json or the raw PVGIS file; the surrounding
sentences describe what those numbers show in the executed run (fingerprint in results/fingerprint.txt)."""
import json, sys, os
import numpy as np, pandas as pd
sys.path.insert(0, '.')
from pv_single_diode import SingleDiodePV

R = json.load(open('results/results.json')); M = pd.read_csv('results/metrics_by_scenario.csv'); H = pd.read_csv('results/metrics_headline.csv', index_col=0)
MM = pd.read_csv('results/mismatch_sweep.csv'); CS = pd.read_csv('results/metrics_coldstart.csv'); CF = pd.read_csv('results/conformal_coverage.csv')
HC = pd.read_csv('results/hybrid_conformal_coverage.csv'); DN = pd.read_csv('results/dnn_offline_metrics.csv'); HO = pd.read_csv('results/hybrid_offline_metrics.csv')
EP = pd.read_csv('results/metrics_shading_episodes.csv'); A = R['data_audit']; FP = open('results/fingerprint.txt').read().strip()
raw = pd.read_csv('PVGIS_Ramadi_2005-2020.csv', skiprows=8); raw['t'] = pd.to_datetime(raw.time, format='%Y%m%d:%H%M'); raw['month'] = raw.t.dt.month; raw['hour'] = raw.t.dt.hour
day = raw['G(i)'] >= 50
HY, PO, IC, P2, AN, SC, DO = 'Hybrid (DNN+P&O)', 'P&O', 'IncCond', 'Poly2(G,T)-MPPT', 'ANN-MPPT', 'Scan+P&O (no ML)', 'DNN scan-only (no P&O)'
def eff(plant, scn, alg): return float(M[(M.plant == plant) & (M.scenario == scn) & (M.algorithm == alg)]['tracking_efficiency_%'].iloc[0])
def col(plant, scn, alg, c): return float(M[(M.plant == plant) & (M.scenario == scn) & (M.algorithm == alg)][c].iloc[0])
def hl(c, alg): return float(H.loc[alg, c])
UNI = ['step_change', 'cloud_passing', 'ramp_change', 'comprehensive', 'real_clear_day', 'real_variable_day']
pvm = SingleDiodePV(); ds = pvm.ds; amb = lambda G, Tc: Tc - (ds['NOCT'] - 20) / 800 * G
v_stc, p_stc, _ = pvm.mpp(1000.0, amb(1000.0, 25.0))
vm = lambda G: pvm.mpp(G, amb(G, 25.0))[0]
slT = 100 * (pvm.mpp(1000.0, amb(1000.0, 45.0))[0] - pvm.mpp(1000.0, amb(1000.0, 25.0))[0]) / 20 / v_stc
gc = R['hybrid_training_compute']; bench = R['compute_benchmark_us']
mmv = lambda sc, sev, alg: float(MM[(MM.scenario == sc) & (MM.severity == sev) & (MM.algorithm == alg)]['tracking_efficiency_%'].iloc[0])
dnn = lambda proto, model: DN[(DN.protocol == proto) & (DN.model.str.startswith(model))].iloc[0]
ho = lambda ts, est: HO[(HO['test set'].str.strip() == ts) & (HO.estimator == est)].iloc[0]
T1 = 'T1 in-distribution (DR plants, mixed shading)'
hc = lambda ts, nom: float(HC[(HC['test set'].str.strip() == ts) & (np.isclose(HC.nominal, nom))].empirical_coverage.iloc[0])
cfv2 = lambda setting, nom: float(CF[(CF.setting.str.strip() == setting) & np.isclose(CF.nominal, nom)].empirical_coverage.iloc[0])
cs_mean = lambda alg: float(CS[(CS.protocol == 'B') & (CS.algorithm == alg)].convergence_steps.mean())
n_succ = lambda alg: int((EP[alg] == 'success').sum())

C = {}
C['B1_01_hist_irradiance'] = f"Distribution of hourly plane irradiance in the PVGIS-SARAH3 series for Ramadi (33.42 N, 43.30 E), 2005-2020 ({A['n_rows']:,} hours). Panel (a) shows all hours on a logarithmic axis: {100*(raw['G(i)']==0).mean():.1f} % of hours are night (G = 0). Panel (b) shows the {int(day.sum()):,} daytime hours (G ≥ 50 W/m²), mean {raw.loc[day,'G(i)'].mean():.0f} W/m², maximum {raw['G(i)'].max():.0f} W/m², with the broad, roughly uniform spread expected for a clear-sky desert site. The controllers and DNNs are only trained and scored on the daytime part."
C['B1_02_hist_temperature'] = f"Distribution of ambient temperature T2m over the same period: mean {raw['T2m'].mean():.1f} °C, range {raw['T2m'].min():.1f} to {raw['T2m'].max():.1f} °C. The bimodal shape reflects the hot summer and cool winter seasons. Because the PV cell temperature adds roughly 0.031 °C per W/m² on top of ambient, the module operates up to ~79 °C, which is what drives the temperature-dependent shift of the maximum-power voltage."
d_ = raw[day]
hiG = raw[raw['G(i)'] > 900]['T2m']; cGT = float(np.corrcoef(d_['G(i)'], d_['T2m'])[0, 1])
C['B1_03_scatter_G_vs_T_by_month'] = f"Daytime (G, T2m) operating conditions coloured by month: {len(d_):,} hours forming {A['n_distinct_GT_daytime']:,} distinct (G, T) pairs (the previous data file contained only 610 distinct rows). Winter months (dark) occupy the cool band (mostly below ~20 °C) at all irradiances up to ~700 W/m², while summer months (light) fill the 30-50 °C band at every irradiance, so temperature is only moderately correlated with irradiance (r = {cGT:.2f}) and the plane is densely covered. High irradiance (> 900 W/m²) occurs almost only in the warmer half of the year (99 % of those hours have T2m ≥ {hiG.quantile(0.01):.0f} °C), which is why cell temperatures of 60-79 °C are reached at the highest irradiances."
pk = raw.groupby(['month', 'hour'])['G(i)'].mean().idxmax()
C['B1_04_heatmap_hour_month_G'] = f"Mean irradiance by hour of day (UTC; local time is UTC+3) and month. Every month and every daylight hour is populated: daytime rows per month are at least {A['min_daytime_rows_per_month']:,}. The maximum mean irradiance occurs in month {pk[0]} at {pk[1]:02d}:00 UTC (solar noon), and the daylight window widens from winter to summer, as it should. This confirms complete seasonal and daily coverage and no time-axis defects."
C['B1_05_representative_days'] = "A winter day and a summer day from the held-out 2019-2020 years (the clearest day of each season). Irradiance (left axis) follows a smooth bell shape that is lower and shorter in winter, while ambient temperature (right axis) lags the irradiance peak by a few hours. These two days illustrate the low-G/low-T and high-G/high-T regimes that bracket the operating conditions in the evaluation."
C['B1_06_sanity_P_vs_G'] = f"Sanity check of the model output computed from the real data. (a) Module maximum-power output P (from the single-diode model) against irradiance for every hour: P is {A['P_max_when_G_zero']:.1f} W whenever G = 0 (red circle) and rises monotonically with G (corr = {A['corr_G_P']:.4f}); the vertical spread at a given G is the temperature effect. (b) Three consecutive days: P follows G exactly in time with no phase offset, which was the defect of the previous data file."
sv = {g: 100 * (vm(g) / v_stc - 1) for g in (100, 200, 400)}
C['B2_01_PV_curve_families'] = f"P-V curve families of the corrected single-diode model (5 parameters, series and shunt resistance, Lambert-W solution) at cell temperatures of 25, 45 and 65 °C and irradiance from 200 to 1000 W/m²; dots mark each curve's maximum power point. The power scales almost proportionally with irradiance, while raising the cell temperature shifts the whole curve to lower voltage and lower power (the open-circuit voltage at 1000 W/m² falls from {float(pvm.voc(1000.0, 25.0)):.1f} V at 25 °C to {float(pvm.voc(1000.0, 65.0)):.1f} V at 65 °C, and the maximum power from {pvm.mpp(1000.0, amb(1000.0, 25.0))[1]:.0f} W at 25 °C to {pvm.mpp(1000.0, amb(1000.0, 65.0))[1]:.0f} W at 65 °C). Note also that the voltage of the maximum drifts with irradiance, which the earlier model could not represent."
C['B2_02_Vmpp_vs_G_and_T'] = f"Voltage at the maximum power point as a function of irradiance (a) and temperature (b). At fixed cell temperature V_mpp decreases logarithmically as irradiance falls: {sv[400]:+.1f} %, {sv[200]:+.1f} % and {sv[100]:+.1f} % relative to STC at 400, 200 and 100 W/m². The temperature dependence is much stronger ({slT:+.2f} %/K of the STC value between 25 and 45 °C cell temperature at 1000 W/m²), so temperature remains the dominant factor (linear R² of V_mpp on temperature alone is {A['vm_linear_R2_T_only']:.2f} versus {A['vm_linear_R2_G_and_T']:.2f} with irradiance added). The old model gave identical V_mpp for all irradiances; this is the physics correction that removed the circularity of the ANN comparison."
C['B2_03_STC_validation'] = f"Validation of the model at Standard Test Conditions against the datasheet points. (a) I-V curve with the datasheet short-circuit current ({ds['Isc']:.2f} A) and open-circuit voltage ({ds['Voc']:.1f} V) marked; the model reproduces both exactly. (b) P-V curve with the datasheet maximum power ({ds['Pmax']:.1f} W) marked; the model's maximum is {p_stc:.2f} W at {v_stc:.2f} V. The temperature coefficients that emerge from the model (dVoc/dT = −0.33 %/K, dPmax/dT = −0.41 %/K) are in the typical range for crystalline silicon and were not imposed."
C['B3_01_loss_curves'] = f"Training and validation loss (mean squared error on the standardised target) against epoch for the three networks: (a) the simple (G,T) model and (b) the complex (G,T,V,I) model, both predicting V_mpp, and (c) the hybrid stage-1 DNN that maps (G, T, 14 scan currents) to the global-MPP voltage and was trained on {gc['train_samples']:,} domain-randomised, partially shaded samples ({gc['dnn_epochs']} epochs, {gc['dnn_train_seconds']:.0f} s). Validation loss tracks training loss closely in all cases, i.e. there is no sign of over-fitting, and early stopping restores the best epoch."
s1s, s1c = dnn('S1', 'ANN (G,T) S1'), dnn('S1', 'ANN (G,T,V,I) S1')
C['B3_02_predicted_vs_actual'] = f"Predicted against actual voltage on held-out data. (a, b) Simple and complex models on the 2019-2020 hours, which the models never saw: R² = {s1s.R2:.4f} and {s1c.R2:.4f}, RMSE = {s1s.RMSE_V:.3f} V and {s1c.RMSE_V:.3f} V. Both are essentially exact because the label is a smooth function of (G, T); the extra V and I inputs of the complex model do not help (they add slight noise). (c) The hybrid stage-1 DNN on the mixed plant/shading test set (R² annotated in the panel), RMSE = {ho(T1, 'Hybrid DNN estimate').RMSE_V:.2f} V. The much larger scatter reflects the genuinely harder multi-peak problem: most points lie on the diagonal, with outliers where a shaded curve has two peaks of similar height and the network picks the wrong one (partially shaded samples in orange)."
C['B3_03_residual_histograms'] = f"Residual (predicted − actual) histograms for the same three models. The simple and complex models have residuals of order 0.01 V, centred on zero. The hybrid DNN's residuals are centred on zero but heavy-tailed: the bulk lies within a few tenths of a volt (MAE {ho(T1, 'Hybrid DNN estimate').MAE_V:.2f} V) while rare wrong-peak choices produce errors of several volts. Such outliers are tolerable in the hybrid architecture because the P&O stage and the periodic re-scan correct the operating point afterwards."
C['B3_04_conformal_calibration'] = f"Empirical coverage of split-conformal prediction intervals against the nominal confidence level (dashed diagonal = ideal). (a) Plain ANN: in distribution (2019-2020) coverage is {cfv2('S1 test (2019-20), calibrated on 2017-18', 0.90):.3f} at the 90 % level and {cfv2('S1 test (2019-20), calibrated on 2017-18', 0.95):.3f} at 95 %, i.e. calibrated, but it falls to {cfv2('... of which G<200 (low light)', 0.90):.2f} in low light and collapses to {cfv2('S2 OUT-OF-RANGE test, calibrated in-range', 0.90):.2f}-{cfv2('S3 OUT-OF-RANGE test, calibrated in-range', 0.90):.2f} for out-of-range temperature or irradiance. (b) Hybrid DNN: {hc(T1, 0.90):.3f} / {hc(T1, 0.95):.3f} on the in-distribution mixture, {hc('T3 nominal plant, partial shading', 0.90):.2f} for shaded nominal-plant samples, and only {hc('T4 OUT-OF-RANGE plants, mixed shading', 0.90):.2f} for plants outside the training range. Conformal intervals are valid marginally and under exchangeability; they are not a safeguard against distribution shift."
td_common = "Top row: power, middle row: PV voltage, bottom row: duty cycle (ideal boost converter, D = 1 − V/V_bus, a display-only signal; no converter dynamics are simulated). Left column: full run; right column: zoom on the shaded window. The dashed black line is the true maximum power point of the actual plant and the grey band is 98-100 % of it. "
C['B4_01_timedomain_step_change'] = f"Irradiance step from 400 to 800 W/m² at t = 1800 s (nominal plant). {td_common}In this single-peak scenario all controllers track the step with negligible loss; the sensor-less P&O/IncCond keep a ±0.5 V dither around V_mpp, the sensor-based controllers (Poly2, ANN) sit still on the model prediction, and the scan-based controllers (Scan+P&O, Hybrid) additionally show short power dips at their periodic scans. Tracking efficiency: P&O {eff('nominal','step_change',PO):.2f} %, ANN {eff('nominal','step_change',AN):.2f} %, Hybrid {eff('nominal','step_change',HY):.2f} %."
C['B4_02_timedomain_cloud_passing'] = f"Periodic cloud-passing scenario (irradiance 400-1200 W/m², slowly varying temperature; nominal plant). {td_common}Differences are small: P&O {eff('nominal','cloud_passing',PO):.2f} %, IncCond {eff('nominal','cloud_passing',IC):.2f} %, Poly2 {eff('nominal','cloud_passing',P2):.2f} %, ANN {eff('nominal','cloud_passing',AN):.2f} %, Hybrid {eff('nominal','cloud_passing',HY):.2f} %. The vertical spikes in the hybrid trace are its scan cycles (about {col('nominal','cloud_passing',HY,'n_scans'):.0f} per hour, costing {col('nominal','cloud_passing',HY,'scan_overhead_%'):.2f} % of the energy)."
C['B4_03_timedomain_ramp_change'] = f"Linear ramp of irradiance and temperature (nominal plant). {td_common}All controllers follow the slowly moving maximum; the voltage reference of the sensor-based controllers tracks the downward drift of V_mpp smoothly, whereas P&O/IncCond step through it in 0.5 V increments. Efficiencies: P&O {eff('nominal','ramp_change',PO):.2f} %, ANN {eff('nominal','ramp_change',AN):.2f} %, Hybrid {eff('nominal','ramp_change',HY):.2f} %."
C['B4_04_timedomain_comprehensive'] = f"Comprehensive scenario with cloud-like irradiance variations and a temperature drift (nominal plant). {td_common}This is the scenario where the sensor-less trackers lose most ({eff('nominal','comprehensive',PO):.2f} % for P&O) because the maximum moves faster; the plain ANN ({eff('nominal','comprehensive',AN):.2f} %) and Poly2 ({eff('nominal','comprehensive',P2):.2f} %) follow it from the model, while the hybrid ({eff('nominal','comprehensive',HY):.2f} %) pays its scan overhead ({col('nominal','comprehensive',HY,'scan_overhead_%'):.2f} %)."
C['B4_05_timedomain_partial_shading'] = f"Nine partial-shading patterns of 400 s each (three bypass-diode substrings, nominal plant). {td_common}P&O, IncCond, Poly2 and the plain ANN lock onto the high-voltage (local) peak in every pattern that has more than one peak (efficiencies {eff('nominal','partial_shading',PO):.1f} %, {eff('nominal','partial_shading',IC):.1f} %, {eff('nominal','partial_shading',P2):.1f} %, {eff('nominal','partial_shading',AN):.1f} %); the scan-based controllers jump to the low-voltage global peak within one or two cycles of each pattern change (Scan+P&O {eff('nominal','partial_shading',SC):.1f} %, Hybrid {eff('nominal','partial_shading',HY):.1f} %). The hybrid and the non-ML scan baseline are indistinguishable here: the global search, not the DNN, is what solves partial shading."
C['B4_06_timedomain_real_clear_day'] = f"A real, clear summer day (2020-06-24) from the held-out PVGIS years, time-compressed to 3600 control cycles (nominal plant). {td_common}All controllers are within {100-min(eff('nominal','real_clear_day',a) for a in (PO,IC,P2,AN,SC,HY)):.2f} percentage points of the maximum; the ANN reaches {eff('nominal','real_clear_day',AN):.3f} %, P&O {eff('nominal','real_clear_day',PO):.2f} % and the hybrid {eff('nominal','real_clear_day',HY):.2f} %. On a smooth real day there is little room for any controller to improve on a well-tuned P&O."
C['B4_07_timedomain_real_variable_day'] = f"A real, variable day (2020-04-06) from the held-out years, time-compressed (nominal plant). {td_common}Efficiencies: P&O {eff('nominal','real_variable_day',PO):.2f} %, IncCond {eff('nominal','real_variable_day',IC):.2f} %, Poly2 {eff('nominal','real_variable_day',P2):.2f} %, ANN {eff('nominal','real_variable_day',AN):.2f} %, Hybrid {eff('nominal','real_variable_day',HY):.2f} %. The ranking matches the synthetic scenarios: the model-based ANN is best on the nominal plant, the hybrid trails it by the scan overhead."
C['B4_08_timedomain_comprehensive_MISMATCHED_plant'] = f"Comprehensive scenario on a plant that differs from the one the ANN and Poly2 were trained on (mismatch severity 1: Iph −8 %, Rs +80 %, Rsh −40 %, n +5 %; the hybrid DNN's domain-randomisation range covers this severity). {td_common}The model-based controllers now sit at a slightly wrong voltage (Poly2 {eff('mismatched','comprehensive',P2):.2f} %, ANN {eff('mismatched','comprehensive',AN):.2f} %) while the perturbing trackers adapt (P&O {eff('mismatched','comprehensive',PO):.2f} %, IncCond {eff('mismatched','comprehensive',IC):.2f} %); the hybrid gets {eff('mismatched','comprehensive',HY):.2f} %."
C['B4_09_timedomain_partial_shading_MISMATCHED_plant'] = f"Partial shading on the mismatched plant. {td_common}The conclusion of the nominal-plant figure is unchanged: the controllers without a global search stay on a local peak ({eff('mismatched','partial_shading',PO):.1f} % for P&O, {eff('mismatched','partial_shading',AN):.1f} % for the ANN) while the scan-based ones reach {eff('mismatched','partial_shading',HY):.1f} % (Hybrid) and {eff('mismatched','partial_shading',SC):.1f} % (Scan+P&O). Scanning measures the actual plant, so it is insensitive to the model mismatch."
C['B4_10_timedomain_real_clear_day_MISMATCHED_plant'] = f"The clear real day on the mismatched plant. {td_common}P&O/IncCond ({eff('mismatched','real_clear_day',PO):.2f} % / {eff('mismatched','real_clear_day',IC):.2f} %) are not affected by the mismatch, whereas the model-based controllers lose accuracy (Poly2 {eff('mismatched','real_clear_day',P2):.2f} %, ANN {eff('mismatched','real_clear_day',AN):.2f} %); the hybrid ({eff('mismatched','real_clear_day',HY):.2f} %) is in between because its P&O stage corrects the DNN estimate."
Bs = CS[CS.protocol == 'B']
C['B4_11_coldstart'] = f"Cold start from the lowest and highest of five valid initial voltages (protocol B: 45-97 % of the open-circuit voltage; G = 800 W/m², T = 25 °C). {td_common.split('Left column')[0]}The four slew-limited controllers (P&O, IncCond, Poly2, ANN: 0.5 V per cycle) need up to {Bs[Bs.algorithm==PO].convergence_steps.max():.0f} (P&O) and {Bs[Bs.algorithm==AN].convergence_steps.max():.0f} (ANN) cycles from the lowest start simply because they must travel the distance at the actuator limit. The scan-based controllers spend the first cycle on a fast I-V sweep (a lossy cycle, plotted at the mean scan power) and then apply the estimated optimum directly: the hybrid holds P/P_mpp ≥ 98 % after {cs_mean(HY):.0f} cycle(s) on average versus {cs_mean(SC):.0f} for Scan+P&O (coarse 2 V probe grid), {cs_mean(PO):.1f} for P&O and {cs_mean(IC):.1f} for IncCond. Caveat: this advantage rests on the assumption that the converter can perform the sweep and the handoff jump without the 0.5 V/cycle limit; with that limit imposed on the handoff the scan-based controllers would converge no faster than the others."
C['B4_12_partial_shading_PV_snapshots'] = f"P-V curve of each of the nine shading patterns (T = 25 °C) with every controller's operating point at the end of its episode (grey band = converter window; × = true global maximum). With one fully lit and heavily shaded substrings the curve has two or three peaks. P&O, IncCond, Poly2 and the ANN stay on the high-voltage local peak in {9-n_succ(PO)} of 9 patterns, losing up to half of the available power; Scan+P&O, DNN scan-only and the Hybrid land on the global maximum in all 9 ({n_succ(PO)}/9 for P&O, {n_succ(AN)}/9 for the ANN, {n_succ(HY)}/9 for the Hybrid, using the criterion that the mean power over the last quarter of an episode reaches 95 % of the global maximum)."
std = ['comprehensive', 'step_change', 'cloud_passing', 'ramp_change']
C['B5_01_tracking_efficiency'] = f"Tracking efficiency (energy-weighted, ΣP/ΣP_mpp) for all seven controllers. (a) Nominal plant on the six uniform-irradiance scenarios (axis zoomed): the plain ANN is best ({hl('eff_std4_nominal_%',AN):.3f} % on the four standard scenarios), P&O/IncCond lose about 0.25 points, and the scan-based controllers are about 0.15 points below P&O because each periodic scan costs energy ({hl('scan_overhead_%_std4',HY):.2f} %); the hybrid averages {hl('eff_std4_nominal_%',HY):.2f} %. (b) Mismatched plant: the ANN drops to {hl('eff_std4_mismatched_%',AN):.2f} % and Poly2 to {hl('eff_std4_mismatched_%',P2):.2f} %, whereas P&O/IncCond ({hl('eff_std4_mismatched_%',PO):.2f} %) and the hybrid ({hl('eff_std4_mismatched_%',HY):.2f} %) are unaffected. (c) Partial shading (full axis): {hl('shading_eff_nominal_%',PO):.1f} % for P&O versus {hl('shading_eff_nominal_%',HY):.1f} % for the hybrid, the single large gain of the new architecture, shared by the non-ML scan baseline ({hl('shading_eff_nominal_%',SC):.1f} %)."
C['B5_02_convergence_time'] = f"Convergence time, defined as the number of control cycles until P/P_mpp stays ≥ 98 % for 10 consecutive cycles. (a) After the start of a run, an irradiance step or a new shading pattern; 'n/c' would mark runs that never converge. In smooth scenarios all controllers converge within a few cycles because V_mpp barely moves; the exceptions are P&O on the real days and Scan+P&O on the variable real day, where a re-scan lands on a coarse probe voltage. (b) Cold start from five valid initial voltages: P&O {cs_mean(PO):.1f}, IncCond {cs_mean(IC):.1f}, Poly2/ANN {cs_mean(AN):.1f}, Scan+P&O {cs_mean(SC):.1f}, DNN-based scan controllers {cs_mean(HY):.1f} cycles on average (bars: mean with min-max whiskers). The DNN's contribution beyond a plain scan is visible only here and in the first cycles after a scan."
C['B5_03_oscillation_amplitude'] = f"Steady-state voltage oscillation (peak-to-peak in quasi-steady 10-cycle windows that contain no scan). P&O and IncCond dither by ≈1 V (one 0.5 V step each way: {hl('osc_amp_V',PO):.2f} V and {hl('osc_amp_V',IC):.2f} V averaged over the standard scenarios), and so do the scan-based controllers whose second stage is P&O ({hl('osc_amp_V',HY):.2f} V for the hybrid). The model-based controllers (Poly2 {hl('osc_amp_V',P2):.2f} V, ANN {hl('osc_amp_V',AN):.3f} V) and the DNN scan-only variant ({hl('osc_amp_V',DO):.3f} V) are nearly ripple-free because they command a smooth reference. The corresponding power oscillation is below 1 % for every controller, so ripple costs little energy on this flat P-V peak."
C['B5_04_compute_cost'] = f"Controller computation per control cycle on a logarithmic axis (mean over the six uniform-irradiance scenarios; Python/Keras on a CPU, decision code only). P&O and IncCond need ≈{hl('compute_us_per_cycle',PO):.1f} µs; Poly2 {hl('compute_us_per_cycle',P2):.0f} µs; the plain ANN {hl('compute_us_per_cycle',AN):,.0f} µs ({hl('compute_us_per_cycle',AN)/hl('compute_us_per_cycle',PO):,.0f}× P&O) because it runs a network forward pass every cycle. The hybrid calls its network only at scans, so its mean cost is {hl('compute_us_per_cycle',HY):.0f} µs ({hl('compute_us_per_cycle',HY)/hl('compute_us_per_cycle',PO):.0f}× P&O, {hl('compute_us_per_cycle',AN)/hl('compute_us_per_cycle',HY):.0f}× less than the plain ANN), with ≈{bench['Hybrid stage-1: DNN call only (scan cycle)']['mean']/1000:.1f} ms on the scan cycles themselves; Keras `predict()` would cost {bench['ANN: model.predict(x)  [Keras high-level API]']['mean']/1000:.0f} ms per call. Absolute values depend on the implementation and hardware; the ratios are the relevant result for embedded or HPC-scale deployment."
C['B5_05_radar_summary'] = f"Summary of seven metrics for all controllers, each axis min-max normalised across the controllers (outer ring = best of the seven; raw values are in the tables). Sensor-less P&O/IncCond are strong on efficiency and compute but weak under shading and slow to start; the plain ANN/Poly2 excel on nominal efficiency and ripple but collapse under shading and degrade under mismatch; Scan+P&O is the all-rounder with the best shading score; the hybrid matches it on shading and mismatch and is the fastest from a cold start, at the price of a small efficiency penalty on uniform irradiance and a few-fold higher compute than P&O."
C['B5_06_mismatch_sweep'] = f"Tracking efficiency against plant-mismatch severity for (a) the comprehensive scenario and (b) partial shading (grey bands: severities outside the hybrid DNN's domain-randomisation box). On the comprehensive scenario the plain ANN falls from {mmv('comprehensive',0.0,AN):.2f} % to {mmv('comprehensive',2.0,AN):.2f} % and Poly2 from {mmv('comprehensive',0.0,P2):.2f} % to {mmv('comprehensive',2.0,P2):.2f} %, crossing below P&O between severity 1 and 1.5; P&O ({mmv('comprehensive',0.0,PO):.2f} → {mmv('comprehensive',2.0,PO):.2f} %) and the hybrid ({mmv('comprehensive',0.0,HY):.2f} → {mmv('comprehensive',2.0,HY):.2f} %) are flat, but the hybrid stays about 0.1-0.15 points below P&O throughout. Under shading the hybrid stays at ≈{mmv('partial_shading',2.0,HY):.0f} % at every severity, while P&O and the ANN remain near 80 % and 76-78 %."
